"""Deterministic OpenFOAM dictionary writer."""

from __future__ import annotations

import math
from typing import Any

from ..version import APP_DISPLAY_NAME, APP_VERSION
from .ast import Dict, Dimensions, Directive, Entry, List, Raw, Str, Tokens, Word

INDENT = "    "
KEY_WIDTH = 16

BANNER = (
    "/*--------------------------------*- C++ -*----------------------------------*\\\n"
    "  Generated by {app} {ver}. This file is regenerated from the project model.\n"
    "  To change it permanently use Expert Mode overrides (they survive regeneration).\n"
    "\\*---------------------------------------------------------------------------*/\n"
)
SEPARATOR = "// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n"
FOOTER = "\n// ************************************************************************* //\n"


def fmt_number(x: Any) -> str:
    if isinstance(x, bool):
        return "true" if x else "false"
    if isinstance(x, int):
        return str(x)
    if not math.isfinite(x):
        raise ValueError("non-finite number")
    if x == 0:
        return "0"
    if float(x).is_integer() and abs(x) < 1e15:
        return str(int(x))
    return repr(float(x))  # shortest exact round-trip representation


def fmt_string(s: str) -> str:
    return '"' + s.replace("\\", "\\\\").replace('"', '\\"') + '"'


_FORBIDDEN_WORD_CHARS = set(' \t\n;{}[]"')


def _balanced_parens(s: str) -> bool:
    depth = 0
    for c in s:
        if c == "(":
            depth += 1
        elif c == ")":
            depth -= 1
            if depth < 0:
                return False
    return depth == 0


def fmt_key(key: str) -> str:
    """Write a keyword.  Keys that are valid OpenFOAM words are written verbatim (a quoted
    key would be interpreted as a regular expression); everything else is quoted."""
    if key.startswith('"') and key.endswith('"') and len(key) >= 2:
        return key
    if key.startswith("${") and key.endswith("}"):
        return key
    if key and key[0] != "(" and not any(c in _FORBIDDEN_WORD_CHARS for c in key) and _balanced_parens(key):
        return key
    return fmt_string(key)


def _inline(value: Any) -> str:
    """Single-line representation (used for scalars, short lists and tokens)."""
    if isinstance(value, (bool, int, float)):
        return fmt_number(value)
    if isinstance(value, Word):
        return value.value
    if isinstance(value, Str):
        return fmt_string(value.value)
    if isinstance(value, Dimensions):
        return "[" + " ".join(fmt_number(e) for e in value.exps) + "]"
    if isinstance(value, Raw):
        return value.text
    if isinstance(value, List):
        return "(" + " ".join(_inline(i) for i in value.items) + ")"
    if isinstance(value, Tokens):
        return " ".join(_inline(i) for i in value.items)
    if isinstance(value, Dict):
        inner = " ".join(f"{fmt_key(e.key)} {_inline(e.value)};" for e in value.entries())
        return "{ " + inner + " }"
    raise TypeError(f"cannot write {type(value).__name__}")


def _is_simple(value: Any) -> bool:
    if isinstance(value, (bool, int, float, Word, Str, Dimensions)):
        return True
    if isinstance(value, Tokens):
        return all(_is_simple(i) for i in value.items)
    if isinstance(value, List):
        items = value.items
        if all(isinstance(i, (bool, int, float, Word, Str)) for i in items):
            return len(items) <= 12
        if all(isinstance(i, List) and all(isinstance(j, (bool, int, float, Word)) for j in i.items) for i in items):
            return len(items) <= 2
        return False
    return False


def _write_value_block(value: Any, level: int, out: list[str]) -> None:
    pad = INDENT * level
    if isinstance(value, Dict):
        out.append(f"{pad}{{\n")
        _write_dict_body(value, level + 1, out)
        out.append(f"{pad}}}\n")
    elif isinstance(value, List):
        out.append(f"{pad}(\n")
        for item in value.items:
            if isinstance(item, Dict):
                _write_value_block(item, level + 1, out)
            elif isinstance(item, List) and not _is_simple(item):
                _write_value_block(item, level + 1, out)
            else:
                out.append(f"{INDENT * (level + 1)}{_inline(item)}\n")
        out.append(f"{pad})")
    else:
        out.append(f"{pad}{_inline(value)}")


def _write_dict_body(d: Dict, level: int, out: list[str]) -> None:
    pad = INDENT * level
    for it in d.items:
        if isinstance(it, Directive):
            arg = "" if it.arg is None else " " + _inline(it.arg)
            out.append(f"{pad}{it.name}{arg}\n")
            continue
        assert isinstance(it, Entry)
        key = fmt_key(it.key)
        v = it.value
        if isinstance(v, Dict):
            out.append(f"{pad}{key}\n")
            _write_value_block(v, level, out)
            if level == 0:
                out.append("\n")
        elif isinstance(v, List) and not _is_simple(v):
            out.append(f"{pad}{key}\n")
            _write_value_block(v, level, out)
            out.append(";\n")
            if level == 0:
                out.append("\n")
        elif isinstance(v, Tokens) and any(isinstance(i, (Dict,)) or (isinstance(i, List) and not _is_simple(i)) for i in v.items):
            # e.g. "nonuniform List<scalar> (...)" or "patch { }" sequences
            head = []
            out.append(f"{pad}{key}")
            for i in v.items:
                if isinstance(i, (Dict, List)) and not _is_simple(i):
                    if head:
                        out.append(" " + " ".join(head))
                        head = []
                    out.append("\n")
                    _write_value_block(i, level, out)
                else:
                    head.append(_inline(i))
            if head:
                out.append(" " + " ".join(head))
            out.append(";\n")
        elif isinstance(v, Raw):
            term = "" if v.text.rstrip().endswith(";") else ";"
            out.append(f"{pad}{key} {v.text}{term}\n")
        elif isinstance(v, Tokens) and not v.items:
            out.append(f"{pad}{key};\n")
        else:
            out.append(f"{pad}{key.ljust(max(KEY_WIDTH, len(key) + 1))}{_inline(v)};\n")


def write_dict_body(d: Dict) -> str:
    out: list[str] = []
    _write_dict_body(d, 0, out)
    return "".join(out)


def write_foam_file(
    body: Dict,
    object_name: str,
    cls: str = "dictionary",
    location: str | None = None,
    fmt: str = "ascii",
    banner: bool = True,
) -> str:
    header = Dict()
    header["version"] = Word("2.0")
    header["format"] = Word(fmt)
    header["class"] = Word(cls)
    if location is not None:
        header["location"] = Str(location)
    header["object"] = Word(object_name)
    parts = []
    if banner:
        parts.append(BANNER.format(app=APP_DISPLAY_NAME, ver=APP_VERSION))
    hdr: list[str] = []
    _write_dict_body(Dict({"FoamFile": header}), 0, hdr)
    parts.append("".join(hdr).rstrip("\n") + "\n")
    parts.append(SEPARATOR + "\n")
    parts.append(write_dict_body(body))
    parts.append(FOOTER)
    return "".join(parts)


def write_value(value: Any) -> str:
    """Text of a single value (for previews and diffs)."""
    out: list[str] = []
    if isinstance(value, (Dict, List)) and not _is_simple(value):
        _write_value_block(value, 0, out)
        return "".join(out)
    return _inline(value)
